240.sql:
WITH c_cols AS (
    SELECT `element`
    FROM atom
    WHERE `molecule_id` = 'TR004'
)
SELECT * FROM c_cols;

291.sql:
SELECT COUNT(*) AS answer
FROM molecule
WHERE `label` = '+';

625.sql:
SELECT COUNT(*) 
FROM users 
WHERE Location LIKE '%New York%';

653.sql:
SELECT OwnerDisplayName
FROM posts
WHERE ViewCount = (SELECT MAX(ViewCount) FROM posts WHERE ViewCount IS NOT NULL);

882.sql:
SELECT MIN(`year`) AS first_year
FROM races
WHERE `name` = 'Singapore Grand Prix';

1035.sql:
SELECT team_fifa_api_id 
FROM Team_Attributes 
WHERE buildUpPlaySpeed > 50 AND buildUpPlaySpeed < 60;
